<script lang="ts">
  import type { Track } from '../types/music'; import type { PlaylistDetails, PlaylistSortMode } from '../types/playlist';
  import { toUiTrack } from '../services/trackMapper';
  import Artwork from '../components/Artwork.svelte'; import Icon from '../components/Icon.svelte'; import TrackRow from '../components/TrackRow.svelte';
  export let playlist: PlaylistDetails; export let current: Track; export let onback: () => void; export let onplay: (track: Track, queue: Track[]) => void; export let onshuffle: (tracks: Track[]) => void; export let onadd: () => void; export let onedit: () => void; export let onmore: (track: Track) => void; export let onfavorite: (track: Track) => void; export let onsort: (mode: PlaylistSortMode) => Promise<void>; export let ondetails: (name: string, description: string) => Promise<void>; export let ondelete: () => Promise<void>; export let onduplicate: () => Promise<void>; export let onclear: () => Promise<void>;
  let sortOpen = false; let detailsOpen = false; let menuOpen = false; let name = playlist.name; let description = playlist.description ?? ''; let busy = false;
  const modes: { value: PlaylistSortMode; label: string }[] = [{value:'custom',label:'Ordem personalizada'},{value:'title',label:'Título'},{value:'artist',label:'Artista'},{value:'album',label:'Álbum'},{value:'recently_added',label:'Adicionadas recentemente'}];
  const formatDuration = (milliseconds: number) => { const minutes = Math.round(milliseconds / 60000); return `${Math.floor(minutes / 60)}h ${minutes % 60}min`; };
  $: uiTracks = playlist.tracks.map(toUiTrack);
</script>
<div class="playlist-screen" style={`--playlist-hue:${Math.abs(playlist.id.length * 37) % 360}`}>
  <header class="playlist-hero"><button onclick={onback} aria-label="Voltar"><Icon name="back" size={28} /></button><Artwork hue={Math.abs(playlist.id.length * 37) % 360} large label={`Capa de ${playlist.name}`} /></header>
  <h1>{playlist.name}</h1>{#if playlist.description}<p class="playlist-description">{playlist.description}</p>{/if}<b class="playlist-owner">Playlist local</b><small class="playlist-duration">{playlist.trackCount} músicas · {formatDuration(playlist.durationMs)}</small>
  <div class="playlist-player-actions"><button class="playlist-menu-button" onclick={() => menuOpen = true} aria-label="Mais opções da playlist"><Icon name="more" /></button><button disabled={!uiTracks.length} onclick={() => onshuffle(uiTracks)} aria-label="Embaralhar playlist"><Icon name="shuffle" size={28} /></button><button class="playlist-play" disabled={!uiTracks.length} onclick={() => uiTracks[0] && onplay(uiTracks[0], uiTracks)} aria-label="Tocar playlist"><Icon name="play" size={30} /></button></div>
  <div class="playlist-tools"><button onclick={onadd}>＋ Adicionar</button><button onclick={onedit}>☰ Editar</button><button onclick={() => sortOpen = true}>↕ Classificar</button><button onclick={() => detailsOpen = true}>✎ Detalhes</button></div>
  {#if uiTracks.length}<div class="playlist-track-list">{#each uiTracks as track (track.id)}<TrackRow {track} active={current.id === track.id} onplay={(selected) => onplay(selected, uiTracks)} {onfavorite} {onmore} />{/each}</div>{:else}<div class="empty-state"><Icon name="music" size={38} /><h2>Playlist vazia</h2><p>Adicione músicas da sua biblioteca.</p><button class="empty-primary" onclick={onadd}>Adicionar músicas</button></div>{/if}
</div>
{#if sortOpen}<div class="modal-backdrop" role="presentation" onclick={(e) => { if (e.target === e.currentTarget) sortOpen=false; }}><div class="action-sheet sort-sheet" role="dialog" aria-modal="true" aria-label="Classificar por"><i></i><h2>Classificar por</h2><div role="radiogroup">{#each modes as mode (mode.value)}<button role="radio" aria-checked={playlist.sortMode === mode.value} onclick={async () => { busy=true; await onsort(mode.value); busy=false; sortOpen=false; }} disabled={busy}><span>{mode.label}</span>{#if playlist.sortMode === mode.value}<Icon name="check" />{/if}</button>{/each}</div></div></div>{/if}
{#if detailsOpen}<div class="modal-backdrop"><form class="action-sheet playlist-details-form" onsubmit={async(e)=>{e.preventDefault();busy=true;await ondetails(name,description);busy=false;detailsOpen=false;}}><h2>Nome e detalhes</h2><label>Nome<input bind:value={name} required maxlength="120" /></label><label>Descrição<input bind:value={description} maxlength="500" /></label><div class="sheet-buttons"><button type="button" onclick={()=>detailsOpen=false}>Cancelar</button><button class="primary" disabled={busy}>Salvar</button></div></form></div>{/if}
{#if menuOpen}<div class="modal-backdrop"><div class="action-sheet"><header><h2>Opções da playlist</h2><button onclick={()=>menuOpen=false} aria-label="Fechar">×</button></header><button class="sheet-action" onclick={async()=>{await onduplicate();menuOpen=false;}}><span>⧉</span><div><b>Duplicar playlist</b><small>Cria uma cópia com a mesma sequência</small></div></button><button class="sheet-action" onclick={async()=>{if(confirm('Remover todas as músicas desta playlist?')){await onclear();menuOpen=false;}}}><span>−</span><div><b>Limpar playlist</b><small>As músicas continuam na biblioteca</small></div></button><button class="sheet-action danger" onclick={async()=>{if(confirm(`Excluir ${playlist.name}? As músicas continuarão na biblioteca.`)){await ondelete();}}}><span>×</span><div><b>Excluir playlist</b><small>Não remove músicas nem arquivos</small></div></button></div></div>{/if}
